import{_ as l,a0 as p,w as a,s as u,I as i,x as t,a1 as o,A as s,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"NVIDIA 的雲遊戲服務 GeForce NOW 無恥地忽略了Linux | LCTT x X-CMD","titleTemplate":false,"description":"NVIDIA 的雲遊戲服務 GeForce NOW 無恥地忽略了Linux | LCTT (202002) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"NVIDIA 的雲遊戲服務 GeForce NOW 無恥地忽略了Linux | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"NVIDIA 的雲遊戲服務 GeForce NOW 無恥地忽略了Linux | LCTT (202002) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202002/20200207 NVIDIA-s Cloud Gaming Service GeForce NOW Shamelessly Ignores Linux","title":"NVIDIA 的雲遊戲服務 GeForce NOW 無恥地忽略了Linux","tag":"202002","desc":""},"relativePath":"202002/20200207 NVIDIA-s Cloud Gaming Service GeForce NOW Shamelessly Ignores Linux.md","filePath":"[post].md"}'),m={name:"202002/20200207 NVIDIA-s Cloud Gaming Service GeForce NOW Shamelessly Ignores Linux.md"};function d(x,e,f,g,N,L){const n=p("Link");return a(),u("div",null,[e[26]||(e[26]=i("h1",{id:"nvidia-的雲遊戲服務-geforce-now-無恥地忽略了linux",tabindex:"-1"},[t("NVIDIA 的雲遊戲服務 GeForce NOW 無恥地忽略了Linux "),i("a",{class:"header-anchor",href:"#nvidia-的雲遊戲服務-geforce-now-無恥地忽略了linux","aria-label":"Permalink to “NVIDIA 的雲遊戲服務 GeForce NOW 無恥地忽略了Linux”"},"​")],-1)),i("p",null,[e[1]||(e[1]=t("NVIDIA 的 ",-1)),o(n,{href:"https://www.nvidia.com/en-us/geforce-now/"},{default:s(()=>[...e[0]||(e[0]=[t("GeForce NOW",-1)])]),_:1}),e[2]||(e[2]=t(" 雲遊戲服務對於那些可能沒有硬件但想使用 GeForce NOW 在最新的最好的遊戲上獲得儘可能好的遊戲體驗玩家來説是充滿前景的（在線推流遊戲，並可以在任何設備上玩）。",-1))]),i("p",null,[e[4]||(e[4]=t("該服務僅限於一些用户（以等待列表的形式）使用。然而，他們最近宣佈 ",-1)),o(n,{href:"https://blogs.nvidia.com/blog/2020/02/04/geforce-now-pc-gaming/"},{default:s(()=>[...e[3]||(e[3]=[t("GeForce NOW 面向所有人開放",-1)])]),_:1}),e[5]||(e[5]=t("。但實際上並不是。",-1))]),e[27]||(e[27]=r('<p>有趣的是，它<strong>並不是面向全球所有區域</strong>。而且，更糟的是 <strong>GeForce NOW 不支持 Linux</strong>。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2020/02/nvidia-geforce-now-linux.jpg?ssl=1" alt=""></p><h3 id="geforce-now-並不是向-所有人開放" tabindex="-1">GeForce NOW 並不是向“所有人開放” <a class="header-anchor" href="#geforce-now-並不是向-所有人開放" aria-label="Permalink to “GeForce NOW 並不是向“所有人開放””">​</a></h3><p>製作一個基於訂閲的雲服務來玩遊戲的目的是消除平台依賴性。</p><p>就像你通常使用瀏覽器訪問網站一樣，你應該能夠在每個平台上玩遊戲。是這個概念吧？</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2020/02/nvidia-geforce-now.png?ssl=1" alt=""></p><p>好吧，這絕對不是火箭科學，但是 NVIDIA 仍然不支持 Linux（和 iOS）？</p><h3 id="是因為沒有人使用-linux-嗎" tabindex="-1">是因為沒有人使用 Linux 嗎？ <a class="header-anchor" href="#是因為沒有人使用-linux-嗎" aria-label="Permalink to “是因為沒有人使用 Linux 嗎？”">​</a></h3><p>我非常不同意這一點，即使這是某些不支持 Linux 的原因。如果真是這樣，我不會使用 Linux 作為主要桌面操作系統來為 “It’s FOSS” 寫文章。</p><p>不僅如此，如果 Linux 不值一提，你認為為何一個 Twitter 用户會提到缺少 Linux 支持？</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2020/02/geforce-now-twitter-1.jpg?ssl=1" alt=""></p><p>是的，也許用户羣不夠大，但是在考慮將其作為基於雲的服務時，<strong>不支持 Linux</strong> 顯得沒有意義。</p>',12)),i("p",null,[e[7]||(e[7]=t("從技術上講，如果 Linux 上沒有遊戲，那麼 ",-1)),e[8]||(e[8]=i("strong",null,"Valve",-1)),e[9]||(e[9]=t(" 就不會在 Linux 上改進 ",-1)),o(n,{href:"https://itsfoss.com/steam-play/"},{default:s(()=>[...e[6]||(e[6]=[t("Steam Play",-1)])]),_:1}),e[10]||(e[10]=t(" 來幫助更多用户在 Linux 上玩純 Windows 的遊戲。",-1))]),e[28]||(e[28]=r('<p>我不想説任何不正確的説法，但台式機 Linux 遊戲的發展比以往任何時候都要快（即使統計上要比 Mac 和 Windows 要低）。</p><h3 id="雲遊戲不應該像這樣" tabindex="-1">雲遊戲不應該像這樣 <a class="header-anchor" href="#雲遊戲不應該像這樣" aria-label="Permalink to “雲遊戲不應該像這樣”">​</a></h3><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2020/02/ge-force-now.jpg?ssl=1" alt=""></p><p>如上所述，找到使用 Steam Play 的 Linux 玩家不難。只是你會發現 Linux 上游戲玩家的整體“市場份額”低於其他平台。</p><p>即使這是事實，雲遊戲也不應該依賴於特定平台。而且，考慮到 GeForce NOW 本質上是一種基於瀏覽器的可以玩遊戲的流媒體服務，所以對於像 NVIDIA 這樣的大公司來説，支持 Linux 並不困難。</p><p>來吧，Nvidia，<em>你想要我們相信在技術上支持 Linux 有困難？或者，你只是想説不值得支持 Linux 平台？</em></p><h3 id="結語" tabindex="-1">結語 <a class="header-anchor" href="#結語" aria-label="Permalink to “結語”">​</a></h3><p>不管我為 GeForce NOW 服務發佈而感到多麼興奮，當看到它根本不支持 Linux，我感到非常失望。</p><p>如果像 GeForce NOW 這樣的雲遊戲服務在不久的將來開始支持 Linux，<strong>你可能沒有理由使用 Windows 了</strong>（<em>咳嗽</em>）。</p><p>你怎麼看待這件事？在下面的評論中讓我知道你的想法。</p><hr>',11)),i("p",null,[e[12]||(e[12]=t("via: ",-1)),o(n,{href:"https://itsfoss.com/geforce-now-linux/"},{default:s(()=>[...e[11]||(e[11]=[t("https://itsfoss.com/geforce-now-linux/",-1)])]),_:1})]),i("p",null,[e[17]||(e[17]=t("作者：",-1)),o(n,{href:"https://itsfoss.com/author/ankush/"},{default:s(()=>[...e[13]||(e[13]=[t("Ankush Das",-1)])]),_:1}),e[18]||(e[18]=t(" 選題：",-1)),o(n,{href:"https://github.com/lujun9972"},{default:s(()=>[...e[14]||(e[14]=[t("lujun9972",-1)])]),_:1}),e[19]||(e[19]=t(" 譯者：",-1)),o(n,{href:"https://github.com/geekpi"},{default:s(()=>[...e[15]||(e[15]=[t("geekpi",-1)])]),_:1}),e[20]||(e[20]=t(" 校對：",-1)),o(n,{href:"https://github.com/wxy"},{default:s(()=>[...e[16]||(e[16]=[t("wxy",-1)])]),_:1})]),i("p",null,[e[23]||(e[23]=t("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[21]||(e[21]=[t("LCTT",-1)])]),_:1}),e[24]||(e[24]=t(" 原創編譯，",-1)),o(n,{href:"https://linux.cn/"},{default:s(()=>[...e[22]||(e[22]=[t("Linux中國",-1)])]),_:1}),e[25]||(e[25]=t(" 榮譽推出",-1))])])}const G=l(m,[["render",d]]);export{T as __pageData,G as default};
